/**
 * Refreshes `types/smileychat-plugin-api.d.ts` from the SmileyChat repo.
 *
 * The typings are generated by the app and committed there, so copying that one
 * file is the whole sync: a plugin can never typecheck against a hand-maintained
 * copy that drifted from the runtime.
 *
 * Usage: `bun run update-types` (optionally `--ref <git ref>` for a branch, tag
 * or commit while testing an unreleased app change).
 */
import { mkdir, writeFile } from "node:fs/promises";
import { dirname, join, resolve } from "node:path";

const rootDir = resolve(import.meta.dir, "..");
const targetPath = join(rootDir, "types", "smileychat-plugin-api.d.ts");

const args = process.argv.slice(2);
const refIndex = args.indexOf("--ref");
const ref = refIndex >= 0 ? args[refIndex + 1] : "main";

if (!ref) {
    console.error("--ref needs a value, for example: bun run update-types --ref v1.2.0");
    process.exit(1);
}

const url = `https://raw.githubusercontent.com/SmileyTatsu/SmileyChat/${ref}/types/smileychat-plugin-api.d.ts`;

const response = await fetch(url);

if (!response.ok) {
    console.error(
        `Could not download ${url} (HTTP ${response.status}). ` +
            "Check the ref and that the SmileyChat build publishes types/smileychat-plugin-api.d.ts.",
    );
    process.exit(1);
}

const typings = await response.text();

if (!typings.includes("export type SmileyPluginApi")) {
    console.error(
        `${url} did not look like SmileyChat plugin typings (no SmileyPluginApi export).`,
    );
    process.exit(1);
}

await mkdir(dirname(targetPath), { recursive: true });
await writeFile(targetPath, typings);

console.log(
    `Updated types/smileychat-plugin-api.d.ts from ${ref} (${typings.split("\n").length} lines).`,
);
